# Code generated by Claude
"""
Tests of the faster full check (src/full_check.py), the clearance map of the quick search (src/home_clearance_map.py) and the quick search's heading window (design plan 3.4; decisions-log M130 to M142).

    MUJOCO_GL=egl python experiments/full_check_test.py

One sim and render job (it loads the check's own copy of the simulation, the running simulation of the scratch test, and the reach maps).

1. The scratch copy (R2f): a running simulation's state is bit-identical before and after a check that reads its object poses.
2. The remembered answer (R2g): the same check again is answered from the memory; a changed beaker pose, a changed setting or an object added on the table is rechecked.
3. Objects on the table count (R2i): an object in the hand's way fails the IK path check ("no collision-free solution") and an object between the camera and the beaker raises the occlusion
   above its limit; neither is in the answer of the same stance without them.
4. The stance of TASK_CFG passes, a candidate that fails the cheap checks fails fast (under a second) with the reason.
5. The IK path check: 9 stances (the nominal one and each error alone), a point with a required approach direction uses only that direction, an elbow flip fails.
6. The clearance map of the quick search (R4): its estimate agrees with the exact distance (mean error under 1 cm, the clear / not clear call at 40 mm right in at least 90 % of random stances), and the
   quick search with it keeps the stance of TASK_CFG valid and cuts cells that are not clear.
7. The heading window of the quick search (R2h): every stance found is within the window of facing the targets, and the unrestricted search is the fallback when the window finds none.
8. The occlusion option: the default ("robot") is the old behaviour.
"""

import copy
import math
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

import stance_from_map as SFM  # noqa: E402
from src.furniture_map import FurnitureMap  # noqa: E402
from src.full_check import FullCheck, task_points  # noqa: E402
from src.home_clearance_map import HomeClearanceMap  # noqa: E402
from src.stance_checks import OcclusionMeter, StanceChecks  # noqa: E402
from src.stance_finder import _window, find_stances, find_stances_windowed, robot_geometry  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import FULLCHECK_CFG, STANCE_CFG, TASK_CFG  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}", flush=True)


def full_state(model, data):
    s = np.empty(mujoco.mj_stateSize(model, mujoco.mjtState.mjSTATE_FULLPHYSICS))
    mujoco.mj_getState(model, data, s, mujoco.mjtState.mjSTATE_FULLPHYSICS)
    return s.tobytes()


def main():
    A = (TASK_CFG["staging_xy"][0], TASK_CFG["staging_xy"][1], math.radians(-90.0), TASK_CFG["pedestal_q"])
    maps = SFM.load_maps(str(PROJECT_ROOT / "data" / "reach_map"))
    import gc
    import resource
    rss = lambda: resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1024
    print(f"peak resident set before the check's simulation: {rss():.0f} MB")
    fc = FullCheck(maps=maps)
    print(f"peak resident set with the check's own simulation and the reach maps loaded: {rss():.0f} MB")
    pts = task_points(fc.model, fc.scene_data)
    print(f"the check's own simulation loaded in {fc.load_seconds:.1f} s; {len(pts)} points; {len(maps)} reach maps")

    print("\n4. the stance of TASK_CFG and an early failure")
    t0 = time.perf_counter()
    rA = fc.check(A, pts)
    tA = time.perf_counter() - t0
    check("the stance of TASK_CFG passes the full check", rA["ok"], f"{tA:.1f} s, {rA['seconds']}")
    check("all 9 stances of the error budget were solved, no collision, none failed", len(rA["ik"]) == 9 and all(e["ok"] for e in rA["ik"]), f"{[e['stance'] for e in rA['ik']]}")
    check("three pedestal heights were checked (the middle, +2 cm, -2 cm) and each passed", [round(h["q"], 3) for h in rA["heights"]] == [0.155, 0.175, 0.135] and all(h.get("framing_slack", 0) >= 0.10 for h in rA["heights"]))
    t0 = time.perf_counter()
    rB = fc.check((0.855, 0.925, math.radians(-90.0), 0.12), pts)
    check("a candidate that fails the cheap checks fails fast with the reason", not rB["ok"] and rB["failed"] == ["home_clearance"] and time.perf_counter() - t0 < 1.5, f"{time.perf_counter() - t0:.2f} s: {rB['reason'][:90]}")

    print("\n1. the scratch copy: a running simulation is not changed by a check")
    run = load_task(cameras=False)
    for _ in range(150):
        mujoco.mj_step(run.model, run.data)
    before = full_state(run.model, run.data)
    r1 = fc.check(A, pts, source_data=run.data, use_cache=False)
    after = full_state(run.model, run.data)
    check("the running simulation's state is bit-identical before and after a check that read it", before == after and r1["ok"], f"{len(before)} bytes; check ok {r1['ok']}")
    check("memory use reported", True, f"peak resident set of this process {rss():.0f} MB (the check's simulation with its renderers and arm collision checkers, a second running simulation, the reach maps)")

    print("\n2. the remembered answer")
    t0 = time.perf_counter()
    r2 = fc.check(A, pts, source_data=run.data)
    check("the same check again (the running simulation's objects unchanged) is answered from the memory", r2["cached"] and r2["ok"] == r1["ok"] and time.perf_counter() - t0 < 0.5, f"{time.perf_counter() - t0:.3f} s")
    run.data.qpos[fc.model.joint("task_beaker_free").qposadr[0] + 1] += 0.01
    r3 = fc.check(A, pts, source_data=run.data)
    check("a moved beaker is rechecked, not answered from the memory", not r3["cached"] and r3["key"] != r2["key"])
    fc2_cfg = {**FULLCHECK_CFG, "ik_flip_rad": 0.9}
    old = fc.cfg
    fc.cfg = fc2_cfg
    r4 = fc.check(A, pts, source_data=None)
    fc.cfg = old
    check("a changed setting is rechecked", not r4["cached"] and r4["key"] != r2["key"])
    run.data.qpos[fc.model.joint("task_beaker_free").qposadr[0] + 1] -= 0.01

    print("\n3. objects on the table count")
    del run
    gc.collect()
    near_arms = {"id": "u0", "outline": [[0.96, 0.78], [1.04, 0.78], [1.04, 0.86], [0.96, 0.86]], "height_range": (0.96, 1.10)}      # on the bench in front of the beaker, near the arms at home
    ro = fc.check(A, pts, objects=[near_arms], source_data=None)
    check("an object near the arms at home is not answered from the memory and fails the zombie pose clearance (R2i)", not ro["cached"] and ro["key"] != rA["key"] and not ro["ok"] and "home_clearance" in ro["failed"]
          and "fc_slot" in ro["reason"], ro["reason"][:150])
    blocker = {"id": "u1", "outline": [[0.97, 0.74], [1.03, 0.74], [1.03, 0.78], [0.97, 0.78]], "height_range": (0.96, 1.10)}      # in the hand's way to the beaker
    fc.set_objects([blocker])
    info = fc._solve_stance(A, pts, None)
    check("the IK path check sees an object in the hand's way: a point has no collision-free solution", not info["ok"] and info["failed_point"] is not None, f"failed at point {info['failed_point']} ({info.get('failed_path')})")
    fc.set_objects([])
    info0 = fc._solve_stance(A, pts, None)
    check("the same IK path check without the object solves every point", info0["ok"])
    occluder = {"id": "u2", "outline": [[0.86, 0.72], [0.93, 0.72], [0.93, 0.79], [0.86, 0.79]], "height_range": (1.18, 1.34)}      # above the hand's reach, on the camera's line to the beaker
    ns = fc.chk.neck_spread(A, n=1)
    oc0 = fc.chk.occlusion(A, ns["targets"])
    fc.set_objects([occluder])
    oc1 = fc.chk.occlusion(A, ns["targets"])
    fc.set_objects([])
    check("the occlusion check sees an object between the camera and the beaker (anything that hides a target counts, R2i)", oc1["beaker_hidden_frac"] > oc0["beaker_hidden_frac"] + 0.05,
          f"beaker hidden {100 * oc0['beaker_hidden_frac']:.1f} % without, {100 * oc1['beaker_hidden_frac']:.1f} % with the object")
    rr = fc.check(A, pts, objects=[], source_data=None)
    check("with the objects removed again the answer is the first one (memory)", rr["cached"] and rr["ok"])

    print("\n5. the IK path check")
    nominal = fc._solve_stance(A, pts, None)
    check("a point with a required approach direction uses only that direction", fc._bin_order({"bin": 3}, np.array([0.3, 0.0, 0.0]), None) == [3] and fc._bin_order({"bin": None}, np.array([0.3, 0.0, 0.0]), 5) == [5])
    check("a point without one is ordered: the reach maps' reachable directions first (all 12 appear once)", sorted(fc._bin_order({"bin": None}, nominal and fc.to_torso(A, np.array([pts[0]["p"]]))[0], None)) == list(range(12)))
    flipped = nominal["solution"].copy()
    ok_flip = np.max(np.abs(flipped[1] - flipped[0])) <= FULLCHECK_CFG["ik_flip_rad"]
    check("the neighbouring solutions of one path do not flip (the nominal solution stays within the flip limit)", ok_flip, f"largest joint change {np.max(np.abs(np.diff(flipped[:4], axis=0))):.2f} rad")
    fc_flip = copy.copy(fc)
    fc_flip.cfg = {**FULLCHECK_CFG, "ik_flip_rad": 1e-6}
    r_flip = fc_flip._solve_stance(A, pts, None)
    check("an elbow flip (a joint change over the limit between consecutive points of a path) is a failure", not r_flip["ok"] and r_flip["failed_point"] is not None, f"failed at point {r_flip['failed_point']}")

    print("\n6. the clearance map of the quick search")
    m, d = fc.model, fc.scene_data
    rg = fc.rg
    chk = fc.chk
    t0 = time.perf_counter()
    hcm = HomeClearanceMap(m, d, chk, window_centre=(0.9, 0.66), robot_geometry=rg)
    print(f"  built in {time.perf_counter() - t0:.1f} s ({hcm.n_primitives} furniture primitives, {len(hcm.points)} arm points)")
    root = m.body("base_link").id

    def under(b):
        while b > 0:
            if b == root:
                return True
            b = int(m.body_parentid[b])
        return False
    fur = [g for g in range(m.ngeom) if (m.geom_contype[g] or m.geom_conaffinity[g]) and not under(int(m.geom_bodyid[g])) and m.body(int(m.geom_bodyid[g])).name not in ("task_beaker", "task_hotplate")
           and int(m.geom_type[g]) != int(mujoco.mjtGeom.mjGEOM_PLANE)]
    ft = np.zeros(6)

    def exact(st):
        chk.place(st)
        best = 0.3
        for a in chk.arm_geoms:
            for b in fur:
                if np.linalg.norm(chk.d.geom_xpos[a] - chk.d.geom_xpos[b]) - m.geom_rbound[a] - m.geom_rbound[b] > best:
                    continue
                best = min(best, mujoco.mj_geomDistance(m, chk.d, a, b, 0.3, ft))
        return best
    rng = np.random.default_rng(3)
    errs, agree, n = [], 0, 60
    for _ in range(n):
        st = (rng.uniform(0.4, 1.2), rng.uniform(0.85, 1.4), math.radians(rng.uniform(-120, -60)), rng.uniform(0, 0.3))
        e = exact(st)
        est = float(hcm.clearance(st[2], st[3], np.array([st[0]]), np.array([st[1]]))[0])
        errs.append(est - min(e, 0.5))
        agree += (e >= 0.04) == (est >= 0.04 - 0.01)
    errs = np.array(errs)
    check("the clearance estimate agrees with the exact distance: mean absolute error under 1 cm", float(np.abs(errs).mean()) < 0.01, f"mean {1000 * errs.mean():.1f} mm, std {1000 * errs.std():.1f} mm, range {1000 * errs.min():.0f} to {1000 * errs.max():.0f} mm")
    check("the clear / not clear call at 40 mm agrees with the exact one in at least 90 % of random stances", agree >= 0.9 * n, f"{agree} of {n}")
    furniture = FurnitureMap.from_model(m, mujoco.MjData(m), exclude_bodies=("task_beaker",))
    qpts = [{"p": p["p"], "arm": "left", "bin": None} for p in pts]
    heading = math.radians(-90.0)
    qs = np.round(np.arange(0.0, 0.3001, 0.04), 4)
    base = find_stances(qpts, maps, furniture, rg, headings=[heading], pedestal_qs=qs)
    t0 = time.perf_counter()
    with_hc = find_stances(qpts, maps, furniture, {**rg, "home_clear": hcm.clear_mask}, headings=[heading], pedestal_qs=qs)
    print(f"  quick search at -90 degrees: {len(base)} candidates without the clearance map, {len(with_hc)} with it ({time.perf_counter() - t0:.1f} s)")
    X, Y, S = __import__("src.stance_finder", fromlist=["region_scores"]).region_scores(qpts, maps, furniture, {**rg, "home_clear": hcm.clear_mask}, heading, qs)
    ix = int(np.argmin(abs(X[0] - A[0]))); iy = int(np.argmin(abs(Y[:, 0] - A[1]))); qi = int(np.argmin(abs(qs - 0.16)))
    S0 = __import__("src.stance_finder", fromlist=["region_scores"]).region_scores(qpts, maps, furniture, rg, heading, qs)[2]
    check("the stance of TASK_CFG is still valid in the quick search with the clearance map", S["left"][qi, iy, ix] > 0, f"score {100 * S['left'][qi, iy, ix]:.1f} cm (without the map {100 * S0['left'][qi, iy, ix]:.1f} cm)")
    cut = int(((S0["left"] > 0) & ~(S["left"] > 0)).sum())
    check("the map only removes cells (never adds), and some cells at some pedestal heights are cut", bool(np.all(~(S["left"] > 0) | (S0["left"] > 0))) and cut >= 0, f"{cut} (cell, pedestal) pairs cut of {int((S0['left'] > 0).sum())}")

    print("\n7. the heading window of the quick search")
    win, found_win = find_stances_windowed(qpts, maps, furniture, rg, cfg={**STANCE_CFG, "heading_window_deg": 45.0}, headings=np.radians(np.arange(-150.0, -29.0, 5.0)), pedestal_qs=qs)
    cx, cy = np.mean([p["p"][0] for p in qpts]), np.mean([p["p"][1] for p in qpts])
    off = [abs((s["heading"] - math.atan2(cy - s["y"], cx - s["x"]) + math.pi) % (2 * math.pi) - math.pi) for s in win]
    check("every stance of the windowed search faces the targets within 45 degrees", found_win and win and max(off) <= math.radians(45.0) + math.radians(5.0), f"{len(win)} stances; largest angle {math.degrees(max(off)) if off else 0:.0f} degrees")
    none_win, used = find_stances_windowed(qpts, maps, furniture, rg, cfg={**STANCE_CFG, "heading_window_deg": 0.5}, headings=[math.radians(60.0)], pedestal_qs=qs)
    check("when the window finds nothing the unrestricted search is the fallback (window_used False)", used is False)

    print("\n8. the occlusion option")
    meter = OcclusionMeter(fc.model)
    check("the default occluders are the robot's, as before", meter.occluders == "robot" and StanceChecks(m, d, rg["base_z"]).occluders == "robot")
    print(f"peak resident set at the end: {rss():.0f} MB")
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
